-- State transitions declared for DataExport: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.data_exports_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('completed', 'expired'), ('pending', 'failed'), ('pending', 'processing'), ('processing', 'completed'), ('processing', 'failed'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: data_exports.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_data_exports__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS data_exports_status_transition_check ON sapiens.data_exports;
CREATE TRIGGER data_exports_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.data_exports
    FOR EACH ROW EXECUTE FUNCTION sapiens.data_exports_status_transition_check();
